// Twilio posts application/x-www-form-urlencoded — n8n parses it into $json.body
const body = $input.first().json.body || {};

const now = new Date();
const dow = now.getDay(); // 0=Sun ... 1=Mon
const diffToMonday = dow === 0 ? -6 : 1 - dow;
const monday = new Date(now);
monday.setDate(now.getDate() + diffToMonday);
const weekStart = monday.toISOString().slice(0, 10);

return [{
  json: {
    smsBody: body.Body || '',
    from: body.From || '',
    messageSid: body.MessageSid || '',
    weekStart,
  }
}];

const ALLOWED = new Set([
  'social_post', 'kwp_class', 'signed_agreement', 'oh_flyer_share',
  'oh_doorknock', 'oh_host', 'oh_followup', 'conversation',
  'command_opportunity', 'cma',
]);

const extracted = $('Extract SMS Fields').first().json;
const claudeResponse = $input.first().json;

function stripFences(text) {
  return text.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
}

let parseError = false;
let activities = [];

try {
  const rawText = claudeResponse.content?.[0]?.text || '';
  const cleaned = stripFences(rawText);
  const parsed = JSON.parse(cleaned);

  if (!Array.isArray(parsed) || parsed.length === 0) {
    parseError = true;
  } else {
    for (const item of parsed) {
      const type = item.activity_type;
      const qty = Number(item.quantity);
      if (!ALLOWED.has(type) || !Number.isFinite(qty) || qty <= 0) {
        parseError = true;
        break;
      }
      activities.push({ activity_type: type, quantity: Math.floor(qty) });
    }
  }
} catch (err) {
  parseError = true;
}

return [{
  json: {
    parseError,
    activities,
    from: extracted.from,
    smsBody: extracted.smsBody,
    weekStart: extracted.weekStart,
  }
}];

function asRows(x) {
  if (Array.isArray(x)) return x;
  if (x && Array.isArray(x.data)) return x.data;
  return x ? [x] : [];
}

const parsed = $('Parse & Validate JSON').first().json;
const rows = asRows($input.first().json);
const total = rows.reduce((sum, r) => sum + (r.points || 0), 0);

const LABELS = {
  social_post: 'post', kwp_class: 'class', signed_agreement: 'agreement',
  oh_flyer_share: 'flyer share', oh_doorknock: 'doorknock', oh_host: 'OH hosted',
  oh_followup: 'OH follow-up', conversation: 'convo',
  command_opportunity: 'Command opp', cma: 'CMA',
};

const summary = parsed.activities
  .map(a => `${a.quantity} ${LABELS[a.activity_type] || a.activity_type}${a.quantity > 1 ? 's' : ''}`)
  .join(', ');

return [{
  json: {
    message: `Logged \u2705 ${summary}. Week so far: ${total} pts.`,
    to: parsed.from,
  }
}];
